"""Transcript merge handler."""

from __future__ import annotations

from typing import ClassVar, List, Optional

import structlog

from rasa.core.channels.conversation_queue.queue import ConversationQueue
from rasa.core.channels.voice_stream.call_state import call_state
from rasa.core.voice.event_composition.events import (
    CompositeEvent,
    UserTranscript,
    metadata_with_merged_transcripts,
)
from rasa.core.voice.event_composition.events.input_events import (
    FinalTranscriptInputEvent,
)
from rasa.core.voice.event_composition.handlers.protocol import (
    RawEventTypes,
)

structlogger = structlog.get_logger()


class TranscriptMergeHandler:
    """Merge consecutive final transcripts within one raw input batch."""

    interested_in: ClassVar[RawEventTypes] = [
        FinalTranscriptInputEvent,
    ]

    def __init__(
        self, interaction_event_queue: ConversationQueue[CompositeEvent]
    ) -> None:
        """Create a transcript merge handler."""
        self.interaction_event_queue = interaction_event_queue
        self._pending_texts: List[str] = []
        self._pending_metadata: Optional[dict] = None
        # Creation time of the latest final transcript in the buffered turn.
        self._last_final_created_at_monotonic: Optional[float] = None

    async def handle(self, event: FinalTranscriptInputEvent) -> None:
        """Buffer a final transcript for the current raw input batch."""
        if self._should_drop_final_as_backchannel(event):
            return

        self._pending_texts.append(event.text)
        self._pending_metadata = event.metadata
        self._last_final_created_at_monotonic = event.created_at_monotonic
        structlogger.debug(
            "transcript_merge_handler.final_transcript_buffered",
            conversation_id=self.interaction_event_queue.conversation_id,
            event_type=type(event).__name__,
            transcript=event.text,
            pending_texts=list(self._pending_texts),
        )

    async def flush_pending_events(self) -> None:
        """Emit the buffered transcript run, if any."""
        if not self._pending_texts:
            return

        merged_transcripts = " ".join(self._pending_texts)
        event = UserTranscript(
            text=merged_transcripts,
            metadata=metadata_with_merged_transcripts(
                self._pending_metadata,
                self._pending_texts,
            ),
            turn_triggered_at_monotonic=self._last_final_created_at_monotonic,
        )
        self._pending_texts.clear()
        self._pending_metadata = None
        self._last_final_created_at_monotonic = None
        await self.interaction_event_queue.put(event)
        structlogger.debug(
            "transcript_merge_handler.user_transcript_enqueued",
            conversation_id=self.interaction_event_queue.conversation_id,
            event_type=UserTranscript.__name__,
            merged_transcript=event.text,
        )

    def _should_drop_final_as_backchannel(
        self, transcript: FinalTranscriptInputEvent
    ) -> bool:
        """Drop overlapping speech as a backchannel unless the user has the floor.

        While audio is playing and interruptable, a final becomes a turn only if an
        accepted barge-in gave the user the floor; otherwise it is a backchannel and
        is dropped.
        """
        if not (
            call_state.is_bot_audio_active
            and call_state.is_interruptable()
            and not call_state.user_has_floor
        ):
            return False

        structlogger.debug(
            "transcript_merge_handler.ignoring_transcript_no_barge_in",
            event_info=(
                "Dropping a final transcript received while an interruptable response "
                "is active: barge-in did not accept it, so it is treated as a "
                "backchannel rather than a turn."
            ),
            conversation_id=self.interaction_event_queue.conversation_id,
            event_type=type(transcript).__name__,
            transcript=transcript.text,
            is_response_active=call_state.is_response_active(),
            is_bot_audio_active=call_state.is_bot_audio_active,
            is_rasa_processing=call_state.is_rasa_processing,
            user_has_floor=call_state.user_has_floor,
            is_interruptable=call_state.is_interruptable(),
        )
        return True
